CREATE INDEX "IX_Match_MascotaUno" ON "Match"("idMascotaUno");
CREATE INDEX "IX_Match_MascotaDos" ON "Match"("idMascotaDos");
CREATE INDEX "IX_Mensaje_Match" ON "Mensaje"("idMatch","fecha");
CREATE INDEX "IX_Voto_Destino" ON "Voto"("idMascotaDestino");
